const body = $input.first().json.body || {};
const now = new Date();
const fmt = (d) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris' }).format(d);
return [{ json: {
  docId: 'cRP1WgZQv7KmwmVrUbuEF8',
  userId: Number(body.userId),
  action: (body.action || 'status').toString(),
  today: fmt(now),
  yesterday: fmt(new Date(now.getTime() - 86400000)),
  now: Math.floor(now.getTime() / 1000),
  hours: Number(body.hours) || 0,
  cardId: body.cardId != null ? Number(body.cardId) : null
} }];

// Expedition (2026-10-04) : jeu d'attente. Le joueur envoie une de ses
// cartes explorer pendant 2h, 8h ou 24h (une seule expedition a la fois),
// puis revient recuperer le butin, tire au sort AU RETOUR (pas au depart :
// rien a deviner en inspectant le reseau). La carte n'est pas bloquee (pure
// mise en scene), mais sa rarete augmente les poussieres rapportees.
function refId(v) { return Array.isArray(v) ? v[1] : v; }
function firstAttachment(v) { if (!Array.isArray(v) || !v.length) return null; const ids = v[0] === 'L' ? v.slice(1) : v; return ids.length ? ids[0] : null; }
function levelForXp(xp) { xp = xp || 0; return Math.floor((25 + Math.sqrt(625 + 100 * xp)) / 50); }
const rand = (a, b) => a + Math.floor(Math.random() * (b - a + 1));

// Paliers de duree : poussieres min/max, chance d'un booster, booster garanti.
const DURATIONS = {
  2:  { dust: [20, 40],   boosterChance: 0.05, guaranteed: 0, label: 'Balade' },
  8:  { dust: [70, 120],  boosterChance: 0.25, guaranteed: 0, label: 'Expédition' },
  24: { dust: [200, 300], boosterChance: 0.30, guaranteed: 1, label: 'Grande aventure' }
};
const RARITY_BONUS = { commune: 1, rare: 1.1, epique: 1.2, legendaire: 1.35, mythique: 1.5 };
const XP_PER_EXPEDITION = 5;
const STORIES = [
  'a fouille une crypte oubliee', 'a traverse une foret enchantee', 'a negocie avec un marchand ambulant',
  'a escalade une montagne de cartes', 'a explore une epave engloutie', 'a dechiffre une carte au tresor',
  'a survecu a une tempete de poussiere d\'etoile', 'a sauve un dragon (enfin, un lezard)'
];

const cfg = $('Set Config').first().json;
const users = $('Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const pulls = $('Get Pulls').all().map((i) => i.json).filter((r) => r.id != null && !r.InVault);
const cards = $('Get Cards').all().map((i) => i.json).filter((r) => r.id != null);
const rarities = $('Get Rarities').all().map((i) => i.json).filter((r) => r.id != null);
const user = users.find((u) => u.id === cfg.userId);
if (!user) return [{ json: { ok: false, error: 'user_not_found' } }];

const rarityById = {}; rarities.forEach((r) => { rarityById[r.id] = r; });
function cardInfo(cardId) {
  const c = cards.find((x) => x.id === cardId);
  if (!c) return null;
  const r = rarityById[refId(c.Rarity)];
  return { cardId: c.id, name: c.Name, imageId: firstAttachment(c.Image), rarity: r ? { key: r.Key, name: r.Name, colorHex: r.ColorHex } : null };
}
const until = user.ExpeditionUntil || 0;
const hours = user.ExpeditionDuration || 0;
const explorer = user.ExpeditionCard ? cardInfo(Number(user.ExpeditionCard)) : null;
const durations = Object.entries(DURATIONS).map(([h, d]) => ({ hours: Number(h), label: d.label, dust: d.dust, boosterChance: d.boosterChance, guaranteed: d.guaranteed }));
const state = until > 0 ? { active: true, until, hours, explorer, secondsLeft: Math.max(0, until - cfg.now), ready: cfg.now >= until } : { active: false };
const base = { now: cfg.now, durations, rarityBonus: RARITY_BONUS, expedition: state };

if (cfg.action === 'status') return [{ json: { ok: true, shouldUpdate: false, payload: base } }];

if (cfg.action === 'start') {
  if (until > 0) return [{ json: { ok: false, error: 'already_running' } }];
  if (!DURATIONS[cfg.hours]) return [{ json: { ok: false, error: 'invalid_duration' } }];
  const owns = pulls.some((p) => refId(p.User) === cfg.userId && refId(p.Card) === cfg.cardId);
  if (!owns) return [{ json: { ok: false, error: 'card_not_owned' } }];
  const newUntil = cfg.now + cfg.hours * 3600;
  // Depart : on n'ecrit QUE les colonnes de l'expedition (noeud dedie), pour
  // ne jamais ecraser un solde modifie entre-temps par une autre action.
  const update = { ExpeditionUntil: newUntil, ExpeditionDuration: cfg.hours, ExpeditionCard: cfg.cardId };
  return [{ json: { ok: true, shouldUpdate: true, startOnly: true, userId: cfg.userId, update,
    payload: { ...base, expedition: { active: true, until: newUntil, hours: cfg.hours, explorer: cardInfo(cfg.cardId), secondsLeft: cfg.hours * 3600, ready: false } } } }];
}

if (cfg.action === 'claim') {
  if (!until) return [{ json: { ok: false, error: 'no_expedition' } }];
  if (cfg.now < until) return [{ json: { ok: false, error: 'not_ready' } }];
  const d = DURATIONS[hours] || DURATIONS[2];
  const bonus = RARITY_BONUS[explorer?.rarity?.key] || 1;
  const dust = Math.round(rand(d.dust[0], d.dust[1]) * bonus);
  const boosters = d.guaranteed + (Math.random() < d.boosterChance ? 1 : 0);
  const newXp = (user.XP || 0) + XP_PER_EXPEDITION;
  const levelsGained = levelForXp(newXp) - levelForXp(user.XP || 0);
  const update = { ExpeditionUntil: 0, ExpeditionDuration: 0, ExpeditionCard: 0,
    StardustCount: (user.StardustCount || 0) + dust, BoosterCount: (user.BoosterCount || 0) + boosters + levelsGained, XP: newXp };
  const story = STORIES[Math.floor(Math.random() * STORIES.length)];
  return [{ json: { ok: true, shouldUpdate: true, userId: cfg.userId, update,
    payload: { ...base, expedition: { active: false }, reward: { dust, boosters, levelsGained, bonus, story, explorer },
      newStardust: update.StardustCount, newBoosterCount: update.BoosterCount, xp: { total: newXp, level: levelForXp(newXp) } } } }];
}
return [{ json: { ok: false, error: 'unknown_action' } }];
